-- Disposable local database only; never production.
do $$begin if current_database()<>'byus_clean' or inet_server_addr() is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create function pg_temp.capsule_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.capsule_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$declare owner uuid:='e9100000-0000-4000-8000-000000000001';other uuid:='e9100000-0000-4000-8000-000000000002';admin uuid:='e9100000-0000-4000-8000-000000000003';campaign uuid;key uuid:=extensions.gen_random_uuid();input jsonb;answer jsonb;balance bigint;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:capsule-test','capsule@example.test'),(other,'did:privy:capsule-other','capsule-other@example.test');
 insert into public.admin_allowlist(id,email,role,active)values(admin,'capsule@example.test','admin',true);
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('a',64),rewards_start_on=current_date;
 perform public.group_wallet_post(owner,'ticket',11,'group_exchange',extensions.gen_random_uuid());
 input:=jsonb_build_object('requestKey',key,'name','Local fixture','blankWeight',0,'prizes',jsonb_build_array(jsonb_build_object('name','A','weight',1000000,'stock',10)));
 answer:=public.group_capsule_dispatch('create',owner,null,input,admin);campaign:=(answer->>'id')::uuid;
 perform pg_temp.capsule_assert(public.group_capsule_dispatch('create',owner,null,input,admin)=answer,'admin creation replays without duplicate campaign');
 perform pg_temp.capsule_error(format('select public.group_capsule_dispatch(''create'',%L,null,%L,%L)',owner,input||'{"name":"Changed"}',admin),'REQUEST_CONFLICT');
 perform pg_temp.capsule_error(format('select public.group_capsule_dispatch(''admin-list'',%L,null,''{}'',%L)',other,admin),'active admin required');
 perform public.group_capsule_dispatch('activate',owner,campaign,'{}',admin);
 key:=extensions.gen_random_uuid();input:=jsonb_build_object('requestKey',key,'count',10);
 answer:=public.group_capsule_dispatch('draw',owner,campaign,input);
 perform pg_temp.capsule_assert(jsonb_array_length(answer->'results')=10 and public.group_wallet_balance(owner,'ticket')=1,'ten draws debit ten once');
 perform pg_temp.capsule_assert((select count(*)from public.group_capsule_fulfillments where owner_id=owner)=10 and (select stock from public.group_capsule_prizes where campaign_id=campaign)=0,'duplicate prize wins create ten fulfillments and consume stock');
 perform pg_temp.capsule_assert((select status from public.group_capsule_campaigns where id=campaign)='paused','any exhausted prize pauses campaign');
 perform pg_temp.capsule_assert(public.group_capsule_dispatch('draw',owner,campaign,input)=answer and public.group_wallet_balance(owner,'ticket')=1,'retry after sold out returns original receipt');
 perform pg_temp.capsule_error(format('select public.group_capsule_dispatch(''draw'',%L,%L,%L)',owner,campaign,input||'{"count":1}'),'REQUEST_CONFLICT');
 perform pg_temp.capsule_error(format('select public.group_capsule_dispatch(''receipt'',%L,null,%L)',other,jsonb_build_object('requestKey',key)),'NOT_FOUND');
 input:=public.group_capsule_dispatch('fulfillments',owner,null,'{}',admin);
 perform pg_temp.capsule_assert(jsonb_array_length(input->'items')=10 and (input->'items'->0) ? 'prize_name' and not ((input->'items'->0) ? 'owner_id'),'fulfillment queue exposes useful labels without raw account IDs');
 input:=jsonb_build_object('id',input->'items'->0->>'id');
 perform public.group_capsule_dispatch('fulfill',owner,null,input,admin);perform public.group_capsule_dispatch('fulfill',owner,null,input,admin);
 perform pg_temp.capsule_assert((select count(*)from public.group_capsule_fulfillments where owner_id=owner and status='fulfilled')=1,'fulfillment retry preserves one completed delivery');
 update public.group_wallet_release set write_fenced=true;
 perform pg_temp.capsule_assert(public.group_capsule_dispatch('receipt',owner,null,jsonb_build_object('requestKey',key))=answer,'receipt readable under write fence');
 update public.group_wallet_release set write_fenced=false;
 input:=jsonb_build_object('requestKey',extensions.gen_random_uuid(),'name','Small stock','blankWeight',500000,'prizes',jsonb_build_array(jsonb_build_object('name','B','weight',500000,'stock',9)));
 campaign:=(public.group_capsule_dispatch('create',owner,null,input,admin)->>'id')::uuid;
 perform public.group_capsule_dispatch('activate',owner,campaign,'{}',admin);
 perform pg_temp.capsule_error(format('select public.group_capsule_dispatch(''draw'',%L,%L,%L)',owner,campaign,jsonb_build_object('requestKey',extensions.gen_random_uuid(),'count',10)),'INSUFFICIENT_STOCK');
 perform pg_temp.capsule_assert(public.group_wallet_balance(owner,'ticket')=1 and (select stock from public.group_capsule_prizes where campaign_id=campaign)=9,'stock failure neither debits nor redraws');
 perform pg_temp.capsule_error(format('select public.group_capsule_dispatch(''draw'',%L,%L,%L)',other,campaign,jsonb_build_object('requestKey',extensions.gen_random_uuid(),'count',1)),'INSUFFICIENT_BALANCE');
 perform pg_temp.capsule_assert((select stock from public.group_capsule_prizes where campaign_id=campaign)=9,'insufficient balance preserves inventory');
 perform pg_temp.capsule_assert(not has_table_privilege('service_role','public.group_capsule_prizes','UPDATE') and not has_function_privilege('authenticated','public.group_capsule_dispatch(text,uuid,uuid,jsonb,uuid)','EXECUTE'),'clients cannot alter probabilities inventory or draw ownership');
end $$;
rollback;
